const PROJECTS = [
  { name: 'Personality.co', id: '31393214664f295f94dd86.76792605' },
  { name: 'Personality - Members area content', id: '9933660066825e9a8005c8.58526829' }
];
const out = [];
for (const p of PROJECTS) {
  out.push({ json: { kind: 'project', project: p.name, project_id: p.id, url: 'https://api.lokalise.com/api2/projects/' + p.id } });
  out.push({ json: { kind: 'statuses', project: p.name, project_id: p.id, url: 'https://api.lokalise.com/api2/projects/' + p.id + '/custom_translation_statuses' } });
  out.push({ json: { kind: 'languages', project: p.name, project_id: p.id, url: 'https://api.lokalise.com/api2/projects/' + p.id + '/languages?limit=100' } });
}
return out;

const req = $('Build Targets').all();
const res = $input.all();
const out = { projects: {}, statuses: {}, languages: {} };
for (let i = 0; i < res.length; i++) {
  const meta = req[i] ? req[i].json : {};
  const body = res[i].json || {};
  const name = meta.project;
  if (meta.kind === 'project') {
    const st = body.statistics || {};
    out.projects[name] = {
      project_id: meta.project_id,
      keys_total: st.keys_total,
      base_words: st.base_words,
      progress_total: st.progress_total,
      qa_issues_total: st.qa_issues_total,
      languages: (st.languages || []).map(l => ({ iso: l.language_iso, id: l.language_id, progress: l.progress, words_to_do: l.words_to_do }))
    };
  } else if (meta.kind === 'statuses') {
    out.statuses[name] = { raw: body, list: (body.custom_translation_statuses || []).map(s => ({ id: s.status_id, title: s.title, color: s.color })) };
  } else if (meta.kind === 'languages') {
    out.languages[name] = (body.languages || []).map(l => ({ id: l.lang_id, iso: l.lang_iso, name: l.lang_name }));
  }
}
return [{ json: out }];
